package decision

import("crypto/sha256";"encoding/hex";"fmt";"strings")

const jevExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationFeedbackCandidateGenerationLoopLSPProjectionBound = "feedback-candidate-generation-loop-lsp-bound"

type JEVExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationFeedbackCandidateGenerationLoopLSPDiagnostic struct { Severity string; Code string; Message string; Status string; MissingStage string; AdmissionFeedbackGenerationChainBridgeDigest string; AdmissionDecision string; CandidateDecision string; RevisionProposalDigest string; GenerationRequestStatus string; GenerationRequestDigest string; GenerationRequestSource string; GenerationRequestEvidenceDigest string; GeneratorIdentity string; FeedbackGenerationRequestBridgeDigest string; ProposalDecision string; DirectionStatus string; Direction string; Target string; FeedbackDigest string; DirectionDigest string; GeneratedCandidateStatus string; GeneratedCandidateDigest string; GeneratedCandidateSource string; GeneratedCandidateEvidenceDigest string; CandidateGenerationFeedbackBridgeDigest string; BridgeDigest string; ProjectionDigest string; Publishable bool; NonExecuting bool; NonAuthorizing bool }

func (d JEVExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationFeedbackCandidateGenerationLoopLSPDiagnostic) Validate() error {
    if d.Severity=="" || d.Code=="" || d.Message=="" || d.Status=="" { return fmt.Errorf("incomplete JEV feedback candidate generation LSP diagnostic") }
    if !d.NonExecuting || !d.NonAuthorizing { return fmt.Errorf("JEV feedback candidate generation LSP diagnostic must be non-executing and non-authorizing") }
    if d.Status==jevExternalApplyCapabilityReviewRevisionCandidateMaterializationAdmissionEvaluationBridgeUnknown { if d.MissingStage=="" || d.Publishable || d.BridgeDigest!="" || d.ProjectionDigest!="" { return fmt.Errorf("unknown JEV feedback candidate generation LSP diagnostic is inconsistent") }; return nil }
    if d.Status!=jevExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationFeedbackCandidateGenerationLoopBridgeBound || !d.Publishable || d.MissingStage!="" || d.AdmissionFeedbackGenerationChainBridgeDigest=="" || d.CandidateGenerationFeedbackBridgeDigest=="" || d.AdmissionDecision=="" || d.GenerationRequestStatus=="" || d.FeedbackGenerationRequestBridgeDigest=="" || d.ProposalDecision=="" || d.Direction=="" || d.GeneratedCandidateStatus=="" || d.BridgeDigest=="" || d.ProjectionDigest=="" { return fmt.Errorf("bound JEV feedback candidate generation LSP diagnostic is incomplete") }
    if d.AdmissionDecision!=d.ProposalDecision { return fmt.Errorf("JEV feedback candidate generation LSP decision drift") }
    expectedDirection:=map[string]string{"revise":jevExternalApplyCapabilityReviewImprovementDirectionGenerate,"retain":jevExternalApplyCapabilityReviewImprovementDirectionHold,"rollback":jevExternalApplyCapabilityReviewImprovementDirectionReject}[d.ProposalDecision]
    if d.Direction!=expectedDirection { return fmt.Errorf("JEV feedback candidate generation LSP direction drift") }
    expected:=digestJEVExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationFeedbackCandidateGenerationLoopLSPProjection(d.Status,d.AdmissionFeedbackGenerationChainBridgeDigest,d.CandidateGenerationFeedbackBridgeDigest,d.ProposalDecision,d.Direction,d.GeneratedCandidateStatus,d.GeneratedCandidateDigest,d.BridgeDigest)
    if d.ProjectionDigest!=expected { return fmt.Errorf("JEV feedback candidate generation LSP projection digest mismatch") }
    return nil
}

func ProjectJEVExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationFeedbackCandidateGenerationLoopLSP(input JEVExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationFeedbackCandidateGenerationLoopBridge) JEVExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationFeedbackCandidateGenerationLoopLSPDiagnostic {
    unknown:=func(stage string) JEVExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationFeedbackCandidateGenerationLoopLSPDiagnostic { if stage=="" { stage="feedback-candidate-generation-loop-lsp" }; return JEVExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationFeedbackCandidateGenerationLoopLSPDiagnostic{Severity:"warning",Code:"jev.provenance.unknown",Message:"Feedback candidate generation loop is UNKNOWN; evidence must be resolved",Status:jevExternalApplyCapabilityReviewRevisionCandidateMaterializationAdmissionEvaluationBridgeUnknown,MissingStage:stage,NonExecuting:true,NonAuthorizing:true} }
    if input.Status==jevExternalApplyCapabilityReviewRevisionCandidateMaterializationAdmissionEvaluationBridgeUnknown { return unknown(input.MissingStage) }
    if err:=input.Validate(); err!=nil { return unknown("feedback-candidate-generation-loop") }
    output:=JEVExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationFeedbackCandidateGenerationLoopLSPDiagnostic{Status:input.Status,AdmissionFeedbackGenerationChainBridgeDigest:input.AdmissionFeedbackGenerationChainBridgeDigest,AdmissionDecision:input.AdmissionDecision,CandidateDecision:input.CandidateDecision,RevisionProposalDigest:input.RevisionProposalDigest,GenerationRequestStatus:input.GenerationRequestStatus,GenerationRequestDigest:input.GenerationRequestDigest,GenerationRequestSource:input.GenerationRequestSource,GenerationRequestEvidenceDigest:input.GenerationRequestEvidenceDigest,GeneratorIdentity:input.GeneratorIdentity,FeedbackGenerationRequestBridgeDigest:input.FeedbackGenerationRequestBridgeDigest,ProposalDecision:input.ProposalDecision,DirectionStatus:input.DirectionStatus,Direction:input.Direction,Target:input.Target,FeedbackDigest:input.FeedbackDigest,DirectionDigest:input.DirectionDigest,GeneratedCandidateStatus:input.GeneratedCandidateStatus,GeneratedCandidateDigest:input.GeneratedCandidateDigest,GeneratedCandidateSource:input.GeneratedCandidateSource,GeneratedCandidateEvidenceDigest:input.GeneratedCandidateEvidenceDigest,CandidateGenerationFeedbackBridgeDigest:input.CandidateGenerationFeedbackBridgeDigest,BridgeDigest:input.BridgeDigest,ProjectionDigest:"",Publishable:true,NonExecuting:true,NonAuthorizing:true,Severity:"info",Code:"jev.provenance.feedback-candidate-generation-loop-bound",Message:"Feedback candidate generation loop is bound without execution or authorization"}
    if input.ProposalDecision=="retain" { output.Code="jev.provenance.feedback-candidate-generation-loop-held"; output.Message="Feedback candidate generation loop is held without execution or authorization" }
    if input.ProposalDecision=="rollback" { output.Severity="warning"; output.Code="jev.provenance.feedback-candidate-generation-loop-rejected"; output.Message="Feedback candidate generation loop is rejected without execution or authorization" }
    output.ProjectionDigest=digestJEVExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationFeedbackCandidateGenerationLoopLSPProjection(output.Status,output.AdmissionFeedbackGenerationChainBridgeDigest,output.CandidateGenerationFeedbackBridgeDigest,output.ProposalDecision,output.Direction,output.GeneratedCandidateStatus,output.GeneratedCandidateDigest,output.BridgeDigest)
    if err:=output.Validate(); err!=nil { return unknown("feedback-candidate-generation-loop-lsp") }
    return output
}

func digestJEVExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationFeedbackCandidateGenerationLoopLSPProjection(status,admissionFeedbackGenerationChainBridgeDigest,candidateGenerationFeedbackBridgeDigest,proposalDecision,direction,generatedCandidateStatus,generatedCandidateDigest,bridgeDigest string) string { sum:=sha256.Sum256([]byte(strings.Join([]string{status,admissionFeedbackGenerationChainBridgeDigest,candidateGenerationFeedbackBridgeDigest,proposalDecision,direction,generatedCandidateStatus,generatedCandidateDigest,bridgeDigest},"|"))); return hex.EncodeToString(sum[:]) }
